custom_css:
/*
*本文件二改自墨千尾（discord@这对吗/inkfoxxxx）老师，非常非常感谢！本质上是为了更贴合自己的美化创造习惯，祝大家游玩愉快~
*配合AI以及VS Code食用
*/
/*美化名称：莓巧电波*/
/*二改作者：江晚*/

/*开始*/
/*一、全局设置*/
/*1.字体导入*/
@import url("https://fontsapi.zeoseven.com/256/main/result.css");/*汇文明朝体*/
@import url("https://fontsapi.zeoseven.com/285/main/result.css");/*思源宋体*/
@import url("https://fontsapi.zeoseven.com/924/main/result.css");/*源样明体*/
@import url("https://fontsapi.zeoseven.com/309/main/result.css");/*京华老宋体*/
/*2.字体名称设置*/

/* 字体名称对照表备忘：
 * 汇文明朝体   -> "Huiwen-mincho"
 * 思源宋体     -> "Noto Serif CJK"
 * 源样明体     -> "GenKiMin2 TC"
 * 京华老宋体   -> "KingHwaOldSong"
 */

/*2.全局控制*/
:root {
/*
* --SmartThemeBodyColor 主要文字颜色
* --SmartThemeEmColor	 斜体文字颜色（即星号包裹的文字）
* --SmartThemeUnderlineColor	 下划线文字颜色
* --SmartThemeQuoteColor	 引用文字（比如 "xxx"）的颜色
* --SmartThemeShadowColor  文字阴影的颜色
* --SmartThemeChatTintColor	 聊天区域的背景颜色
* --SmartThemeBlurTintColor	 侧边栏、弹出菜单等UI面板的背景颜色  
* --SmartThemeBorderColor	 UI面板的边框颜色  
* --SmartThemeUserMesBlurTintColor	 用户聊天气泡的背景颜色
* --SmartThemeBotMesBlurTintColor	 AI角色的聊天气泡背景颜色
* --fontScale	 字体比例
* --sheldWidth	 页面宽度
* --blurStrength	 背景模糊强度
* --shadowWidth	 文字阴影宽度
* --bg-thumb-columns   聊天背景缩略图列数*/
}
/*以上为酒馆原生变量*/

/*3.全局字体设置*/
body {
  font-family: "KingHwaOldSong",sans-serif !important; /* 字体名称，或font-family: var(--字体1); 后面那个是常见备用字体，你也可以自己改 */
  font-weight: normal; /* 字重，一般情况下无需特殊设置 */
  font-style: normal; /* 样式，一般情况下无需特殊设置。有normal（常规）和italic（斜体）等 */
  font-size:13.5px;
}

/*全局部分结束*/

/*二、弹出面板*/
/*1.顶栏弹出面板*/
/*整体*/
.drawer-content {
  background-color:transparent !important;
  background-image:url('https://i.ibb.co/67RPfL4m/drawer.png') !important;
  background-size: cover;
  background-position:center;
  background-repeat: no-repeat; /* 如果你不想要背景图的话可以加上这条 */
  /* (可选) 同时统一它们的边框颜色 */
  border-color:transparent !important;
  color:#4f6271 !important;
  /*字体设置*/
  font-size: 13px;
  font-family:"KingHwaOldSong";
}

#table_drawer_content {
  background-color:transparent !important;
  background-image:url('https://i.ibb.co/67RPfL4m/drawer.png') !important;
  background-size: cover;
  background-position:center;
  background-repeat: no-repeat; /* 如果你不想要背景图的话可以加上这条 */
  /* (可选) 同时统一它们的边框颜色 */
  border-color:transparent !important;
  color:#4f6271 !important;
  /*字体设置*/
  font-size: 13px;
  font-family:"KingHwaOldSong";
}

/*小控件设置*/
small{
    color:#778ca4 !important;
}

.menu_button{
color:#e1d9d9 !important;/*方形按键*/
}
/*按键内部*/
.fa, .fa-brands, .fa-classic, .fa-regular, .fa-sharp, .fa-solid, .fab, .far, .fas{
    color:#4f6271 !important;
}
/*复选框（勾选框）设置*/
/* 1) 框:大小 / 边框 / 圆角 / 底色都在这里改 */
input[type="checkbox"] {
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;

    position: relative;               /* 图片定位的基准,不能省 */
    overflow: visible !important;     /* 关键①:允许图片伸出框外 */
    clip-path: none;                  /* 若还有clip限制也一并放行 */

    width: 13px;        /* ← 框宽 */
    height: 13px;       /* ← 框高 */
    margin: 3px 3px 0 0;
    vertical-align: middle;

    background-color: transparent !important;    /* ← 框底颜色 */
    border: 0.5px solid #ababdc23 !important;    /* ← 框边框:粗细+颜色 */
    border-radius: 5px !important;               /* ← 框圆角 */
    box-shadow: none;
    cursor: pointer;
}

/* 2) 图片:改用绝对定位、以框中心为基准,不再被框束缚 */
input[type="checkbox"]::before {
    content: '' !important;
    position: absolute !important;    /* 关键②:脱离input的内容盒 */
    left:-5%;
    top: 35%;

    width: 20px;    /* ← 图宽:设得比框大,就会自然溢出框外 */
    height: 20px;   /* ← 图高 */
    margin: 0.5px;

    background-image: url("https://i.ibb.co/rR1kt3gZ/image.png") !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    rotate: -5deg; /* 可选:旋转角度,正值顺时针,负值逆时针 */

    clip-path: none !important;   /* 去掉ST剪的√ */
    box-shadow: none !important;  /* 去掉ST的√颜色 */
    pointer-events: none;         /* 图片别挡点击 */
}

/* 3) 显示/隐藏 */
input[type="checkbox"]:not(:checked)::before {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0);
}
input[type="checkbox"]:checked::before {
    opacity: 1;
    transform: translate(-20%, -40%) scale(1);
}

/*2.底部弹出面板*/
/*整体外部*/
#options, #extensionsMenu, .popup .popper-modal{
    box-shadow: none !important;    
    background-color: transparent !important;
}
/*整体内部*/
.options-content {
  background-color:transparent !important;
  background-image:url('https://i.ibb.co/1FFkW4w/option.png') !important;
  background-size: cover;
  background-position:center;
  background-repeat: no-repeat; /* 如果你不想要背景图的话可以加上这条 */
  /* (可选) 同时统一它们的边框颜色 */
  border-color:#999999 !important;
  border:1px !important;
}

/*内部设置*/
.options-content span{
  font-family:"KingHwaOldSong";
   color:#778ca4 !important;
   font-size:14.5px;
}

#extensionsMenu>.extension_container>div, #extensionsMenu>div:not(.extension_container), .options-content a, .list-group-item {
  font-family:"KingHwaOldSong";
   color:#778ca4 !important;
   font-size:14.5px;
}
/*3.弹出面板统一性设置*/
/* 清除原生样式 + 统一渐变（与滑动条一致） */
.margin0,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background: transparent;
    border: none !important;
    box-shadow: none !important;
}

/* 表单控件文字格式统一+背景透明 */
.text_pole,
.range-block-counter input,
input,
select,
button,
textarea {
    font-family: "GenKiMin2 TC", serif !important;
    font-weight: normal !important;
    font-style: normal !important;
    color: #4c5965 !important;
    background: transparent !important;
    border:none;
    font-size: 13.5px !important;
    line-height: 1.6em !important;
}

/* select2 下拉控件透明化 + 字体与面板一致 */
.select2-container .select2-selection--multiple,
.select2-container .select2-selection--single,
.select2_choice_clickable_buttonstyle+span.select2-container .select2-selection__choice__display {
    background-color: transparent !important;
    border-color:none !important;
    font-family: "KingHwaOldSong", serif !important;
    color: #949ea8 !important;
    font-size: 13px !important;
}

/* 清除伪元素 */
.margin0::before,
.margin0::after,
#extensions_settings .inline-drawer-toggle.inline-drawer-header::before,
#extensions_settings .inline-drawer-toggle.inline-drawer-header::after,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header::before,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header::after,
#user-settings-block h4::before,
#user-settings-block h4::after,
.standoutHeader::before,
.standoutHeader::after {
    content: none !important;
    display: none !important;
}

/* 提示词管理器条目文字颜色 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: #4f6271  !important;
    font-family: "KingHwaOldSong", serif !important;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span{
    color: #4f6271  !important;
    box-shadow: none !important;
    filter: drop-shadow(0px 0px 2px rgba(0, 0, 0, 0.2));
}
/*提示词*/
#completion_prompt_manager .completion_prompt_manager_header_advanced span{
    filter: drop-shadow(0px 0px 2px rgba(0, 0, 0, 0));
    color: #4f6271  !important;
}

#bg_tabs .bg_tabs_list .bg_tab_button a{
    color:#4f6271 !important;
    font-size: 13px !important;
    font-family: "KingHwaOldSong", serif !important;
}

#bg-header-fixed{
    background-color:transparent;
}

#bg_tabs.ui-widget-content{
     background-color: transparent;
}

.select2-dropdown{
    box-shadow: 0 0 2px #f4f4f4e8!important;
}

.menu_button_icon span{
    color:#4f6271d0 !important;
}

.justifyLeft{
    color:#6e7984
}

.toggle-description{
    color:#6e7984d9 ;
}

#tagInput{
    color: #b3bfcb !important;
}
/*欢迎面板统一化*/
.ui-sortable-handle{
    border-radius: 8px !important;
border-color: #4f6271bb !important;
}

body.bubblechat .welcomePanel {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

.welcomeRecent .recentChatList .recentChat{
    color:#374b5a !important;
}

/*弹出面板部分结束*/

/*三、顶栏设置*/
/*方案一：背景图覆盖*/
#top-bar{
    box-shadow: none !important;
    background-color:transparent !important ;

}
/* 1.顶栏装饰图 */
#top-settings-holder::before {
    content: "";
    position: absolute;

    top: -8px;
    left: 50%;
    transform: translateX(-50%);

    width: 105%;
    height: 310px;

    background: url("https://i.ibb.co/1JK18PDX/image.png")
                center top
                / 100% auto
                no-repeat;

    z-index: 1;
    pointer-events: none;
}

/*2.顶栏图标（背景图之上）*/
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden; 
}

#top-settings-holder .drawer {
    flex: 1; 
}

#top-settings-holder .drawer-icon {
    display: block; 
    margin: 0 auto;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 0px; /* 图标宽度 */
    height:0px; /* 图标高度 */
    opacity: 1 !important;
}

#top-settings-holder > * {
    position: relative;
    z-index: 2;
}


/*方案二：正常不覆盖顶栏*/
/*1.顶栏整体设置*/
.disabled{
#top-settings-holder {
    background-size: 100% 100%; /* （可选）背景图长宽都拉伸到容器的100%，可自行修改为具体数值或其他百分比，或使用长宽自适应“auto”（比较适合没有具体图案的背景图）。更多效果问AI */
    background-position: center;
    background-image:linear-gradient(to right, #6e0f18a1, #f4e3ef) ; /* 不要背景图的话可以在这直接设置背景颜色（要了也不影响，实心图会直接覆盖颜色，镂空图会透出颜色 */
    box-shadow: none;
    border: ✏️px solid ✏️; /* 边框，铅笔处分别填“边框粗细数值”和“颜色”。如果使用变量，格式为“var(变量名)”，如“var(--main-text-color)”，不要遗漏“--”! */
    border-radius: ✏️px; /* （可选）圆角数值 */
}

/* （如果选用了顶栏圆角，则保留这部分代码）确保父容器圆角 */
#top-bar {
    border-radius: ✏️px !important; /* 与顶栏一致的圆角数值 */
    background-color:linear-gradient(to right, #6e0f18a1, #f4e3ef) !important;
    box-shadow: none !important;
    border: none !important;
}

/*2.顶栏图标设置*/
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden; 
}

#top-settings-holder .drawer {
    flex: 1; 
}

#top-settings-holder .drawer-icon {
    display: block; 
    margin: 0 auto;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 30px; /* 图标宽度 */
    height: 30px; /* 图标高度 */
    opacity: 1 !important;
}

/* （可选）悬停效果 */
.drawer-icon.fa-fw:hover {
    transform: scale(1.2);
}

/* 关闭状态图标（如果想每个图标展开时样式都不一样，可将以下部分替换为①中“图标1”~“图标10”后，将所有“content:''”都替换为“background-image: url('')”，再单独设置即可。同理，如果想让①的代码精简，则将以下代码替换过去，由background-image: url('')改为content:'' */
.drawer-icon.fa-sliders {
   background-image: url('https://i.ibb.co/p6G1QnTb/1.png'); /* AI响应配置 */
}

.drawer-icon.fa-plug {
   background-image: url('https://i.ibb.co/ymLbWKmp/2.png'); /* API连接 */
}

.drawer-icon.fa-font {
   background-image: url('https://i.ibb.co/v6tFH3tc/3.png'); /* AI回复格式化 */
}

.drawer-icon.fa-book-atlas {
   background-image: url('https://i.ibb.co/Swfp3tFf/4.png'); /* 世界信息 */
}

.drawer-icon.fa-user-cog {
   background-image: url('https://i.ibb.co/SDmR20YD/5.png'); /* 用户设置 */
}

.drawer-icon.fa-panorama {
   background-image: url('https://i.ibb.co/ZpP87bkV/6.png'); /* 背景图 */
}

.drawer-icon.fa-cubes {
   background-image: url('https://i.ibb.co/PsfJ18Sm/7.png'); /* 扩展 */
}

.drawer-icon.fa-bars-progress {
   background-image: url('https://i.ibb.co/d44t1gVJ/8png.png'); /* 记忆表格 */
}

.drawer-icon.fa-face-smile {
   background-image: url('https://i.ibb.co/d44t1gVJ/8png.png'); /* 用户角色管理 */
}

.drawer-icon.fa-address-card {
   background-image: url('https://i.ibb.co/XfHS5Mq1/9.png'); /* 角色卡 */
}

/* （可选）展开状态图标 */
#top-settings-holder .drawer .drawer-icon.openIcon {
    background-image: url(✏️) !important; /* 统一替换为同一个图标 */
    transform: scale(1.2); 
}
}
/*滑动条与滚动条设置*/
/*1.滚动条-隐藏*/
::-webkit-scrollbar {
    display: none;
    width: 0 !important;
    height: 0 !important;
}
::-webkit-scrollbar-track {
    display: none;
}
::-webkit-scrollbar-thumb {
    display: none;
}
/* Firefox 兼容 */
* {
    scrollbar-width: none;
}

/*2.滑动条-美化*/
/* 重置所有 <input type="range"> 的默认浏览器样式 */
input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    width: 100%;
    background: transparent !important;
    border: none !important;      /* 去掉滑动条本体边框 */
    outline: none !important;     /* 去掉聚焦时的外框 */
    box-shadow: none !important;  /* 去掉可能的阴影 */
    cursor: pointer;
    filter: brightness(0.95) !important; /* 轻微调暗，防止过亮 */
}
/* 设计滑块的“轨道” (Track) */
input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;
    height: 6px; /* 轨道的粗细，自调 */
    /* 轨道的背景现在是一个静态的、完整的渐变色，渐变颜色自调下边两个数值，调整原理和上边那个一样 */
    background: linear-gradient(to right, #d5dbe290, #778ca4c1);
    border-radius: 4px;
    border: none !important;
}

/* 设计滑块的“手柄” (Thumb) - 使用自定义图标 */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;    
    margin-top: -10px; /* 图标（手柄）的上下距离，改了大小就要改这里哦，确保滑动的图标在滑动条上 */
    height: 30px; /* 高度 */
    width: 30px; /* 宽度 */

    /* 图标替换，自改 */
    background-image: url('https://i.ibb.co/XrB2X1JH/image.png');
    rotate: 15deg; /* 可选:旋转角度,正值顺时针,负值逆时针 */   
    filter:brightness(1);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    filter:none !important; /* 去掉滤镜，防止图标变淡 */
    /* 移除所有可能导致“变淡”的默认样式 */
    background-color: transparent; 
    border: none !important;
    border-radius: 0;
    box-shadow: none;
    transition: transform 0.2s ease; /* 保留悬停放大动画 */
}

/*  当鼠标悬停或拖动时，让手柄稍微变大 */
input[type="range"]:hover::-webkit-slider-thumb,
input[type="range"]:active::-webkit-slider-thumb {
    transform: scale(1.2);
}

/* 兼容Firefox浏览器 */
input[type="range"]::-moz-range-track {
    height: 8px; /* 图标（手柄）的上下距离 */
    background: linear-gradient(to right, #d5dbe290, #778ca4c1); /* 改色和上边一样 */
    border-radius: 3px;
    border: none;
}

input[type="range"]::-moz-range-thumb {
    height: 28px;
    width: 28px; /* 大小自调  */
    background-image: url('https://i.ibb.co/1JK18PDX/image.png'); /* 图标替换 */
    rotate: 15deg; /* 可选:旋转角度,正值顺时针,负值逆时针 */   
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    background-color: transparent;
    border: none;
    border-radius: 0;
}
/*顶栏部分结束*/

/*四、底栏设置*/
/*1.整体*/
#send_form {
  position: relative;
  background: rgba(0, 0, 0, 0.8) !important; /* 基础底色 */
  border: none !important;
  margin-top: 0px !important;
}

/* 利用伪元素贴上你的撕裂边缘图片 */
#send_form::after {
  content: '' !important;
  position: absolute;
  bottom: 0px; /* 根据图片高度调整 */
  left: 0;
  width: 110%;
  height:150%; /* 边缘装饰的高度 */
  background: url('https://i.ibb.co/7dt7BbvM/image.png') no-repeat center;
  background-size: cover;
  pointer-events: none;
}
#sheld, 
#send_form {
  overflow: visible !important; /* 核心：允许内容溢出容器边界 */
  position: relative !important;
}

#form_sheld.compact{
     background-color:transparent !important; 
}
/*2.输入框设置*/
#send_textarea{
  border-radius: 12px !important; /* 输入框圆角 */
  /* （可选）珍珠分享的代码：输入框上端不被遮挡+输入框完全隐藏，按需选择 */
  /* 顶部边框完整显示 */
  clip-path: none !important;
  /* 输入框完全隐藏 */
  background-color: transparent !important;
  border-color: transparent !important;
}

/*3.图标替换*/
/* 基础设置 */
#send_form [class*="fa-"]::before {
  content: '' !important;
  display: inline-block;
  width: 30px; /* 图片宽度 */
  height: 30px; /* 图片高度 */
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  vertical-align: middle;
}

/* 菜单 */
#options_button::before {
  background-image: url('https://i.ibb.co/XrB2X1JH/image.png') !important;
position:absolute;
  top:-2px !important;
}

/* 扩展 */
#extensionsMenuButton::before {
  background-image: url('https://i.ibb.co/70pfx5F/image.png') !important;
  position:absolute;
  width:36px !important;
  height: 36px !important;
  top:-5px !important;
}

/* QR */
#quick-reply-rocket-button i::before {
  background-image: url('https://i.ibb.co/kgrj8vjB/image.png') !important;
width:36px !important;
  height: 36px !important;
  position:relative;
  top:-5px !important;
}

/* 发送 */
#send_but::before {
  background-image: url('https://i.ibb.co/9mTZrgTF/image.png') !important;
  width:36px !important;
