  /* 设置字体大小，并设置样式 */
  font-size: 12px !important; /* 自定义文字的大小 */
  color: transparent !important; /* 自定义文字的颜色 */
  text-shadow: 0 0 5px rgba(0, 0, 0, 0); /* 自定义文字阴影，不要就改成text-shadow: none;或删掉这一行 */
}

/* 3. 添加鼠标悬停效果 */
